// 1. Получаем первый входящий элемент и извлекаем HTML строку по указанному пути.
const firstItem = $('Webhook2').first();
// Используем оператор опциональной цепочки ?. для безопасного доступа на случай, если путь не существует.
const htmlString = firstItem?.json?.body?._embedded?.threads?.[0]?.body;

// Проверяем, получили ли мы строку для обработки.
if (typeof htmlString !== 'string') {
    // Возвращаем пустой результат и сообщение об ошибке, если строка не найдена или некорректна.
    // Убедись, что следующий узел обрабатывает этот случай (например, If нод)
    return [{
        json: {
            telegramHtml: '',
            error: 'Input HTML string not found or invalid type at specified path'
        }
    }];
}

// 2. Очистка и преобразование HTML для Telegram с использованием \n для переносов строк

let cleanedHtml = htmlString;

// --- Шаг 1: Преобразование сущностей и удаление мусора ---

// Декодируем основные HTML сущности, если они есть.
// Вместо замены   на пробел или что-то другое, мы его удалим.
cleanedHtml = cleanedHtml.replace(/ /g, ''); // Удаляем сущность  
// Удаляем также сам символ неразрывного пробела (U+00A0), который может быть вставлен напрямую
cleanedHtml = cleanedHtml.replace(/&nbsp;/g, ''); // <-- Удаляем символ неразрывного пробела

// Добавьте сюда другие сущности по мере необходимости, например:
// cleanedHtml = cleanedHtml.replace(/&/g, '&');
// cleanedHtml = cleanedHtml.replace(/</g, '<');
// cleanedHtml = cleanedHtml.replace(/>/g, '>');


// Удаляем комментарии <!-- ... -->
cleanedHtml = cleanedHtml.replace(/<!--.*?-->/gs, '');

// Удаляем теги <script>, <style> и их содержимое
cleanedHtml = cleanedHtml.replace(/<(script|style)\b[^>]*>.*?<\/\1>/gs, '');
cleanedHtml = cleanedHtml.replace(/<(script|style)\b[^>]*\/>/gi, ''); // Самозакрывающиеся теги script/style

// Заменяем все варианты тегов переноса строки (<br>, <br/>, <br attr="...">) на символ \n
cleanedHtml = cleanedHtml.replace(/<br\b[^>]*?>/gi, '\n');

// Преобразуем <p> теги в переносы строк. </p> -> \n\n, <p> -> удаляем.
// Используем \n вместо <br>
cleanedHtml = cleanedHtml.replace(/<\/p\b[^>]*?>/gi, '\n\n');
cleanedHtml = cleanedHtml.replace(/<p\b[^>]*?>/gi, '');

// Удаляем неподдерживаемые контейнерные теги (div, span, font и т.п.), сохраняя их содержимое.
// Используем более точный regex, который учитывает возможные атрибуты.
cleanedHtml = cleanedHtml.replace(/<\/?(div|span|font|o:p|xml|del:\w+)\b[^>]*?>/gi, '');


// --- Шаг 2: Удаление атрибутов и неподдерживаемых тегов ---

// Удаляем ВСЕ атрибуты из тегов, кроме 'href' из <a>.
// Этот regex находит ОТКРЫВАЮЩИЕ теги с опциональными атрибутами.
cleanedHtml = cleanedHtml.replace(/<([a-z]+)(?:\s+[^>]*?)?>/gi, (match, tagName, attributes) => {
    tagName = tagName.toLowerCase();

    // Проверяем, является ли это тегом <a>
    if (tagName === 'a') {
        // Если это тег <a>, пытаемся найти атрибут href
        if (attributes) { // Проверяем, были ли вообще атрибуты
            const hrefMatch = attributes.match(/href\s*=\s*["']([^"']*)["']/i);
             // Если href найден, не пустой и не только пробелы
             if (hrefMatch && hrefMatch[1] && hrefMatch[1].trim() !== '') {
                // Возвращаем тег <a> только с атрибутом href
                return `<a href="${hrefMatch[1]}">`;
             }
        }
        // Если это тег <a>, но нет href, или он некорректен/пуст, удаляем тег
        return '';
    }

    // Для всех остальных тегов, проверяем, является ли он поддерживаемым Телеграмом
    // (b, i, u, s, code, pre - <br> уже заменен на \n)
    const supportedTags = ['b', 'strong', 'i', 'em', 'u', 's', 'del', 'code', 'pre'];
     if (supportedTags.includes(tagName)) {
         // Если поддерживаемый, возвращаем тег без каких-либо атрибутов
         return `<${tagName}>`;
     }

    // Если тег не <a> и не поддерживается, удаляем его (оставляя содержимое)
    return '';
});

// Удаляем также закрывающие теги, которые не поддерживаются (оставляя их содержимое)
// Поддерживаемые закрывающие теги останутся (</b>, </i> и т.д.)
cleanedHtml = cleanedHtml.replace(/<\/?(?!b|strong|i|em|u|s|del|code|pre|a\b)[a-z]+\b[^>]*?>/gi, '');


// --- Шаг 3: Чистка пробелов и переносов строк ---

// Удаляем пустые поддерживаемые теги, которые могли остаться после удаления содержимого (кроме <a>)
// Например, <b></b>, <i></i> и т.д.
cleanedHtml = cleanedHtml.replace(/<(b|strong|i|em|u|s|del|code|pre)\s*>\s*<\/\1>/gi, '');

// Схлопываем множественные обычные пробелы и табуляции в один пробел.
// Это важно после удаления   и символа  , чтобы не осталось много пробелов.
cleanedHtml = cleanedHtml.replace(/[ \t]+/g, ' ');


// Удаляем пробелы, которые стоят непосредственно перед \n
cleanedHtml = cleanedHtml.replace(/ +\n/g, '\n');


// Нормализуем последовательности \n (оставляем максимум два \n подряд для имитации абзаца)
// Заменяем 3 и более \n (возможно, с пробелами или табами между ними, которые уже должны быть удалены
// на предыдущих шагах) на два \n.
cleanedHtml = cleanedHtml.replace(/\n{3,}/g, '\n\n');

// Удаляем пробелы/табы, которые примыкают к одиночным \n.
cleanedHtml = cleanedHtml.replace(/[ \t]*\n[ \t]*/g, '\n');

// И снова нормализуем множественные \n после предыдущей чистки (на случай, если \n\n стали \n\n\n и т.п.)
cleanedHtml = cleanedHtml.replace(/\n{3,}/g, '\n\n');


// Удаляем ведущие/завершающие пробелы и \n
cleanedHtml = cleanedHtml.trim(); // Удаляет начальные/конечные пробелы и символы новой строки


// 3. Возвращаем результат в формате, ожидаемом n8n узлом Code.
// Возвращаем массив с ОДНИМ объектом.
return [{
    json: {
        telegramHtml: cleanedHtml // Очищенная строка с \n для Telegram
    }
}];

function cleanAndFormatText(input) {
  if (typeof input !== 'string') return input;
  let text = input;

  // 1. Нормализуем переводы строк
  text = text.replace(/\r\n?/g, '\n');

  // 2. Обрамляем <li> переносами, чтобы надёжно их найти
  text = text.replace(/<li\b[^>]*>/gi, '\n<li>');
  text = text.replace(/<\/li>/gi, '</li>\n');

  // 3. Убираем теги <ul> и </ul>
  text = text.replace(/<\/?ul[^>]*>/gi, '\n');

  // 4. <br> → перевод строки
  text = text.replace(/<br\s*\/?>/gi, '\n');

  // 5. Преобразуем <li>…</li> в "- …"
  text = text.replace(
    /<li>\s*([\s\S]*?)\s*<\/li>/gi,
    (_, content) => '- ' + content.trim()
  );

  // 6. Декодируем HTML-сущности
  text = text
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&laquo;/g, '"')
    .replace(/&raquo;/g, '"')
    .replace(/&mdash;/g, '-')
    .replace(/&ndash;/g, '–');

  // 7. Сохраняем жирный: <b>…</b> → **…**
  text = text.replace(/<(b|strong)>(.*?)<\/\1>/gi, '**$2**');

  // 8. Удаляем все оставшиеся теги
  text = text.replace(/<[^>]+>/g, '');

  // 9. Преобразуем markdown-жирный обратно в HTML <b>
  text = text.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');

  // 10. Чистим пробелы и «сжимаем» пустые строки
  text = text
    .replace(/[ \t]+\n/g, '\n')    // убираем trailing spaces
    .replace(/\n{3,}/g, '\n\n')   // не более двух переносов подряд
    .trim();

  return text;
}


// --- Функция 2: глубокая нормализация отступов и пустых строк ---
function deepCleanAndFormat(text) {
  if (typeof text !== 'string') return text;

  const lines = text.split('\n').map(l => l.trim());
  const out = [];
  let empty = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line === '') {
      empty++;
      if (empty <= 2) out.push('');
    } else {
      empty = 0;
      out.push(line);
    }
  }

  // сжимаем лишние переводы после сбора
  return out
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// --- Основной код для n8n ---
const agentItem = $('AI Agent2').first();
if (!agentItem || !agentItem.json || typeof agentItem.json.output !== 'string') {
  return [{ json: { error: "Нет текстовой строки в поле output." } }];
}

const raw = agentItem.json.output;

// Шаг 1. Преобразуем HTML → markdown-подобный текст
const step1 = cleanAndFormatText(raw);

// Шаг 2. Убираем лишние пустые строки и нормализуем отступы
const formattedOutput = deepCleanAndFormat(step1);

// Возвращаем результат
return [{
  json: {
    output: formattedOutput,
    originalOutput: raw
  }
}];

const data = $('Тянем пользователя3').first().json;
let customerId = 10000000; // Значение по умолчанию

if (data && data._embedded && data._embedded.customers && data._embedded.customers.length > 0 && data._embedded.customers[0].id) {
  customerId = data._embedded.customers[0].id;
}

return [{ json: { customerId } }];

// --- 1) Функция: чистим HTML, преобразуем списки и абзацы в переносы и буллеты ---
function cleanAndFormatText(input) {
  if (typeof input !== 'string') return '';
  let t = input;

  // Удаляем контейнеры <div>
  t = t.replace(/<\/?div[^>]*>/gi, '');

  // 1) <li>…</li> → "\n- текст"
  t = t
    .replace(/<li[^>]*>/gi, '\n- ')
    .replace(/<\/li>/gi, '\n');

  // 2) Теги списков → разделитель строки
  t = t
    .replace(/<ul[^>]*>/gi, '')
    .replace(/<\/ul>/gi, '\n')
    .replace(/<ol[^>]*>/gi, '')
    .replace(/<\/ol>/gi, '\n');

  // 3) Параграфы → "\n\n"
  t = t.replace(/<p[^>]*>/gi, '').replace(/<\/p>/gi, '\n\n');

  // 4) <br> → "\n"
  t = t.replace(/<br\s*\/?>/gi, '\n');

  // 5) Удаляем прочие теги, кроме <b>, <i>, <u>
  //    Негативный lookahead не затрагивает нужные теги
  t = t.replace(/<\/?(?!\/?(?:b|i|u)\b)[^>]+>/gi, '');

  // 6) Декодируем HTML-сущности
  t = t
    .replace(/&nbsp;/g, ' ')
    .replace(/&mdash;|&ndash;/g, '-')
    .replace(/&quot;/g, '"')
    .replace(/&laquo;|«/g, '«')
    .replace(/&raquo;|»/g, '»')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&period;/g, '.')
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(d));

  // 7) Убираем пробелы перед переносами и обрезаем края
  return t.replace(/[ \t]+\n/g, '\n').trim();
}

// --- 2) Функция: нормализуем пустые строки и вложенность буллетов ---
function deepCleanAndFormat(text) {
  if (typeof text !== 'string') return '';
  const lines = text.split('\n').map(l => l.trim());

  // Убираем подряд >2 пустых строк
  const cleaned = [];
  let emptyCount = 0;
  for (const ln of lines) {
    if (!ln) {
      emptyCount++;
      if (emptyCount <= 2) cleaned.push('');
    } else {
      emptyCount = 0;
      cleaned.push(ln);
    }
  }

  // Восстанавливаем вложенность:
  // если предыдущая строка кончилась ":", а текущая - "- ",
  // добавляем 4 пробела перед "- "
  for (let i = 1; i < cleaned.length; i++) {
    if (/[: ]$/.test(cleaned[i - 1]) && cleaned[i].startsWith('- ')) {
      cleaned[i] = '    ' + cleaned[i];
    }
  }

  // Собираем и сжимаем пустые строки до не более двух подряд
  let result = cleaned.join('\n').trim();
  result = result.replace(/\n{3,}/g, '\n\n');

  return result;
}

// --- 3) Основная логика n8n Code-узла ---
const rawHtml = $('Webhook2').first().json.body._embedded.threads[0].body;

// Шаг 1: очистка и базовое форматирование
const step1 = cleanAndFormatText(rawHtml);

// Шаг 2: глубокая чистка, нормализация пустых строк и вложенности
const formattedText = deepCleanAndFormat(step1);

// Выводим оригинал и отформатированный результат
return [{
  json: {
    original: rawHtml,
    formattedText
  }
}];

// 1. Получаем все входящие элементы.
// $input.all() возвращает массив объектов n8n.
const items = $input.all();

// Инициализируем переменную для хранения всех найденных ID
const allCustomerIds = [];

// 2. Перебираем каждый входящий элемент и извлекаем ID клиентов.
for (const item of items) {
// Проверяем, существует ли нужная вложенная структура и массив клиентов
// Используем оператор опциональной цепочки ?. для безопасного доступа
const customersArray = item?.json?._embedded?.customers || item?._embedded?.customers;

// Если массив клиентов найден и является массивом, извлекаем ID
if (Array.isArray(customersArray)) {
const idsFromThisItem = customersArray
.map(customer => customer?.id) // Извлекаем id каждого клиента (ожидаем число)
.filter(id => id !== undefined && id !== null); // Убираем null/undefined

// Добавляем найденные ID в общий список
allCustomerIds.push(...idsFromThisItem);
}
}

// 3. Определяем конкретное число, которое мы хотим проверить на наличие.
// !!! ВАЖНО: ЗАМЕНИ ЧИСЛО 5521 НА НУЖНОЕ ТЕБЕ ЧИСЛО !!!
const specificTargetId = $('Webhook2').first().json.body._embedded.threads[0].createdBy.id; // Например, проверяем наличие числа 5521

// 4. Проверяем, содержит ли массив allCustomerIds это конкретное число.
// Используем простой метод .includes().
const foundSpecificId = allCustomerIds.includes(specificTargetId);

// 5. Возвращаем результат в формате, ожидаемом n8n узлом Code (true или false).
// Возвращаем массив с одним объектом, содержащим результат в свойстве 'json'.
return [{
json: {
specificIdFound: foundSpecificId,
returrn: allCustomerIds // Ключ будет содержать true или false
}
}];

// Получаем текст из Whatsapp Webhook, если он есть
const telegramText = $('Whatsapp Webhook').first()?.json?.body?.messageData?.extendedTextMessageData?.text || $('Whatsapp Webhook').first()?.json?.body?.messageData?.textMessageData?.textMessage;

let openAIContent = null;
try {
  openAIContent = $('OpenAI').first()?.json?.text;
} catch (error) {
  // Обрабатываем случай, когда OpenAI не был выполнен
  if (error.message && (error.message.includes('Referenced node is unexecuted') || error.message.includes("hasn't been executed"))) {
    openAIContent = null;
  } else {
    throw error;
  }
}

// Формируем итоговый текст
let resultText = "";
if (telegramText) {
  resultText = telegramText;
} else if (openAIContent) {
  resultText = `Транскрибация: ${openAIContent}`;
}

// Заменяем переносы строк на ". " и экранируем спецсимволы
const safeText = resultText
  .replace(/[\r\n]+/g, '. ')
  .replace(/\\/g, '\\\\')
  .replace(/"/g, '\\"');

return [
  {
    json: {
      text: safeText,
    },
  },
];

