// --- Функция для преобразования HTML-подобной разметки в WhatsApp Markdown ---
function formatForWhatsapp(text) {
  if (typeof text !== 'string') return text;

  let formattedText = text;

  // 1. Заменяем HTML теги жирного на звездочки WhatsApp
  // <b>текст</b>  ->  *текст*
  formattedText = formattedText.replace(/<b>(.*?)<\/b>/gi, '*$1*');

  // 2. Добавим правила для курсива и зачеркнутого на всякий случай
  // <i>текст</i>  ->  _текст_
  formattedText = formattedText.replace(/<i>(.*?)<\/i>/gi, '_$1_');
  // <s>текст</s>  ->  ~текст~
  formattedText = formattedText.replace(/<s>(.*?)<\/s>/gi, '~$1~');

  // 3. На всякий случай удаляем любые оставшиеся HTML-теги, которые могли просочиться
  formattedText = formattedText.replace(/<[^>]+>/g, '');

  // 4. Возвращаем полностью готовый для WhatsApp текст
  return formattedText;
}


// --- Основной код для n8n ---

// 1. Получаем данные из предыдущего узла (где вы запускали первый скрипт)
const previousNodeItem =  $input.first();
if (!previousNodeItem || !previousNodeItem.json || typeof previousNodeItem.json.output !== 'string') {
  return [{ json: { error: "Не найден результат от предыдущего узла форматирования." } }];
}

// 2. Берем уже отформатированный текст
const textToConvert = previousNodeItem.json.output;

// 3. Запускаем новую функцию для преобразования в формат WhatsApp
const whatsappFormattedText = formatForWhatsapp(textToConvert);

// 4. Возвращаем финальный результат
return [{
  json: {
    // Теперь поле называется 'output', как в первом скрипте
    output: whatsappFormattedText
  }
}];

// --- 1) Функция: чистим HTML, преобразуем списки и абзацы в переносы и буллеты ---
function cleanAndFormatText(input) {
  if (typeof input !== 'string') return '';
  let t = input;

  // Удаляем контейнеры <div>
  t = t.replace(/<\/?div[^>]*>/gi, '');

  // <li>…</li> → "\n- текст"
  t = t
    .replace(/<li[^>]*>/gi, '\n- ')
    .replace(/<\/li>/gi, '\n');

  // Теги списков → разделитель строки
  t = t
    .replace(/<ul[^>]*>/gi, '')
    .replace(/<\/ul>/gi, '\n')
    .replace(/<ol[^>]*>/gi, '')
    .replace(/<\/ol>/gi, '\n');

  // Параграфы → "\n\n"
  t = t.replace(/<p[^>]*>/gi, '').replace(/<\/p>/gi, '\n\n');

  // <br> → "\n"
  t = t.replace(/<br\s*\/?>/gi, '\n');

  // Удаляем все теги, кроме <b>, <i>, <u>
  t = t.replace(/<\/?(?!\/?(?:b|i|u)\b)[^>]+>/gi, '');

  // Декодируем HTML-сущности
  t = t
    .replace(/&nbsp;/g, ' ')
    .replace(/&mdash;|&ndash;/g, '-')
    .replace(/&quot;/g, '"')
    .replace(/&laquo;|«/g, '«')
    .replace(/&raquo;|»/g, '»')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&period;/g, '.')
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(d));

  // Убираем пробелы перед переносами и обрезаем края
  return t.replace(/[ \t]+\n/g, '\n').trim();
}

// --- 2) Функция: нормализуем пустые строки и вложенность буллетов ---
function deepCleanAndFormat(text) {
  if (typeof text !== 'string') return '';
  const lines = text.split('\n').map(l => l.trim());

  // Убираем подряд >2 пустых строк
  const cleaned = [];
  let emptyCount = 0;
  for (const ln of lines) {
    if (!ln) {
      emptyCount++;
      if (emptyCount <= 2) cleaned.push('');
    } else {
      emptyCount = 0;
      cleaned.push(ln);
    }
  }

  // Восстанавливаем вложенность:
  for (let i = 1; i < cleaned.length; i++) {
    if (/[: ]$/.test(cleaned[i - 1]) && cleaned[i].startsWith('- ')) {
      cleaned[i] = '    ' + cleaned[i];
    }
  }

  // Сжимаем пустые строки
  let result = cleaned.join('\n').trim();
  result = result.replace(/\n{3,}/g, '\n\n');

  return result;
}

